#[test]
fn external_agent_process_cancel_terminates_child() {
    #[cfg(windows)]
    let (program, args) = (
        "ping",
        vec![
            std::ffi::OsString::from("127.0.0.1"),
            std::ffi::OsString::from("-n"),
            std::ffi::OsString::from("30"),
        ],
    );
    #[cfg(not(windows))]
    let (program, args) = ("sleep", vec![std::ffi::OsString::from("30")]);

    let mut process = ExternalAgentProcess::spawn(
        std::ffi::OsStr::new(program),
        &args,
        &std::env::temp_dir(),
        &[],
    )
    .expect("spawn cancellable external process");
    process.cancel().expect("cancel external process");
    assert!(
        process
            .poll_exit()
            .expect("poll cancelled external process")
            .is_some()
    );
}

